#!/bin/bash
# Bring the staging stack up.
#
# Idempotent: generates .env on first run, runs preflight.sh, builds the image,
# starts the stack and waits for /healthz. Everything it writes stays inside
# deploy/staging (`.env` is git-ignored) — no secrets are committed. Preflight
# failing stops the deploy before the build; SKIP_PREFLIGHT=1 skips it.
set -euo pipefail
cd "$(dirname "$0")"

if [ ! -f .env ]; then
  echo "up.sh: creating .env with fresh secrets"
  cat > .env <<EOF
# Generated by up.sh on $(date -u +%Y-%m-%dT%H:%M:%SZ). Do not commit.
DB_ROOT_PASSWORD=$(openssl rand -hex 24)
FAX_SESSION_SECRET=$(openssl rand -hex 32)
FAX_PUBLIC_ORIGIN=https://fax-staging.lab.innotel.us
# Filled in from the "Innotel Fax Staging" Authentik application.
FAX_OIDC_ISSUER=https://auth.cerulean.innotel.us/application/o/innotel-fax-staging/
FAX_OIDC_CLIENT_ID=innotel-fax-staging
FAX_OIDC_CLIENT_SECRET=replace-with-the-staging-client-secret
FAX_ALLOWED_GROUPS=Zeus,Capstone
FAX_ADMIN_GROUPS=cerulean-platform
FAX_CALLER_ID=fax-staging@lab.innotel.us
# The proxy's LAN address: the portal cannot reach auth.cerulean.innotel.us
# through the WAN hairpin (see compose.yml), so the name is pinned internally.
FAX_OIDC_INTERNAL_ADDR=${FAX_OIDC_INTERNAL_ADDR:-192.168.1.71}
EOF
  chmod 600 .env
fi

# Gate the deploy on the checks the portal has to pass. The sign-in check runs
# against the stack that is live now: if that is broken, replacing the image is
# not the fix, and shipping the new one would hide the reason.
if [ "${SKIP_PREFLIGHT:-0}" != "1" ]; then
  ./preflight.sh
fi

docker build --build-arg "APT_CHECK_DATE=${APT_CHECK_DATE:-true}" -t innotel/fax-portal:staging ../..
docker compose --env-file .env up -d --remove-orphans

for _ in $(seq 1 60); do
  if curl -fsS http://127.0.0.1:3997/healthz >/dev/null 2>&1; then
    echo "up.sh: $(curl -s http://127.0.0.1:3997/healthz)"
    exit 0
  fi
  sleep 2
done

echo "up.sh: the portal did not become healthy; last 40 log lines:" >&2
docker compose --env-file .env logs --tail 40 portal >&2
exit 1
